-- AKEMI JAPAN — JFT-Basic 50 Soal (25 FOTO + 25 AUDIO)
-- Soal latihan original bergaya JFT-Basic, bukan soal resmi JFT.
alter table questions add column if not exists audio_text text;

do $$ declare pid uuid; begin
  select id into pid from parts where part_number=1 limit 1;
  if pid is null then
    values (1,'JFT-Basic — 50 Soal','Latihan JFT-Basic: 25 soal foto + 25 soal audio. Pilih jumlah soal dan timer sendiri.',50,true,true,true) returning id into pid;
  else
    update parts set name='JFT-Basic — 50 Soal', description='Latihan JFT-Basic: 25 soal foto + 25 soal audio. Pilih jumlah soal dan timer sendiri.', question_limit=50, shuffle_questions=true, shuffle_options=true, active=true where id=pid;
  end if;
  delete from questions where part_id=pid;
end $$;
notify pgrst, 'reload schema';
